void file_errors() {
    ::tpyapp::main::write("gzip_basic_plain.bin", ::tpy::bytes_literal("not gzip at all", 15));
    ::tpyapp::main::load_attempt("file not gzip", "gzip_basic_plain.bin");
    ::tpy::ByteArray bad_crc = ::tpy::ByteArray(FIXTURE);
    ::tpy::bytearray_setitem(bad_crc, (::tpy::sub_check<int32_t>(::tpy::__len__(bad_crc), 8)), static_cast<uint8_t>(::tpy::bytes_getitem(bad_crc, (::tpy::sub_check<int32_t>(::tpy::__len__(bad_crc), 8))) ^ 1));
    ::tpyapp::main::write("gzip_basic_crc.gz", ::tpy::Bytes(bad_crc));
    ::tpyapp::main::load_attempt("file crc", "gzip_basic_crc.gz");
    ::tpyapp::main::write("gzip_basic_trunc.gz", ::tpy::Bytes(::tpy::bytes_slice(FIXTURE, ::tpy::BasicSlice{std::nullopt, (::tpy::sub_check<int32_t>(::tpy::__len__(FIXTURE), 3))})));
    ::tpyapp::main::load_attempt("file truncated", "gzip_basic_trunc.gz");
    ::tpyapp::main::write("gzip_basic_trail.gz", (::tpy::bytes_concat(FIXTURE, ::tpy::bytes_literal_owned("junk", 4))));
    ::tpyapp::main::load_attempt("file trailing", "gzip_basic_trail.gz");
    ::tpyapp::main::write("gzip_basic_empty.gz", ::tpy::BytesView{});
    ::tpyapp::main::load_attempt("file empty", "gzip_basic_empty.gz");
    ::tpystd::gzip::GzipFile f = ::tpystd::gzip::open("gzip_basic_plain.bin");
    f.close();
    std::cout << "file lazy" << " " << ::tpy::print_bool(f.closed()) << "\n";
    {
        try {
            ::tpystd::gzip::open("gzip_basic_missing.gz");
        } catch (const ::tpy::FileNotFoundError& e) {
            std::cout << "file missing" << " " << std::string(::tpy::__str__(e)) << "\n";
        }
    }
    ::tpystd::os::mkdir("gzip_basic_dir");
    {
        try {
            ::tpystd::gzip::open("gzip_basic_dir");
        } catch (const ::tpy::IsADirectoryError& e) {
            std::cout << "file directory" << " " << std::string(::tpy::__str__(e)) << "\n";
        }
    }
}

